  let days=[-6,-5,-4,-3,-2,-1,0].map(n=>{let d=addDays(new Date(),n),on=streak.set.has(localDateKey(d)),label=d.toLocaleDateString("pt-BR",{weekday:"short",day:"2-digit"});return '<div class="day '+(on?"active":"")+'">'+(on?LSIcon("streak","icon-sm"):"<span>○</span>")+'<b>'+label+'</b></div>'}).join("");
