  '<div class="surface tracking-wide"><div class="dash-card-title">'+LSIcon("sequence")+'<h3>Progresso por módulo</h3></div><div class="sequence-list" style="margin-top:14px">'+snap.moduleRows.map((x,i)=>'<div class="sequence-item '+(x.complete?"done":"")+'"><span class="dot">'+(x.complete?"✓":i+1)+'</span><span>'+esc(moduleLabel(x.name))+' · '+x.done+'/'+x.total+' aulas</span></div>').join("")+'</div></div>';
  if(window.LSHydrateIcons)LSHydrateIcons(root);
