function llTextVariants(text){let raw=String(text||"").trim().replace(/\s+/g," "),out=[raw];let cleaned=raw.replace(/^(sinal|palavra|resposta|aprenda|pratique)\s*(de|da|do|:|-)?\s*/i,"").trim();if(cleaned&&cleaned!==raw)out.push(cleaned);if(raw.includes(":")){let tail=raw.split(":").slice(1).join(":").trim();if(tail)out.push(tail)}return[...new Set(out.filter(Boolean))]}
async function buildLibrasLabCandidates(raw){await catalog();let map=new Map,owned=new Set(S.signs.map(x=>x.norm));for(let d of(raw||[])){let matched=null;for(let variant of llTextVariants(d.text)){let os=opts(variant);if(os.length){matched={variant,options:os};break}}if(!matched)continue;let canonical=matched.options[0].label.replace(/\d+$/,"").trim()||matched.variant,k=norm(canonical),cur=map.get(k);if(!cur){cur={name:title(canonical),norm:k,count:0,existing:owned.has(k),uiLikely:LL_UI_WORDS.has(k),options:matched.options,raw:[]};map.set(k,cur)}cur.count+=Math.max(1,+d.count||1);if(d.text&&!cur.raw.includes(d.text))cur.raw.push(d.text)}return[...map.values()].sort((a,b)=>(a.uiLikely-b.uiLikely)||(b.count-a.count)||a.name.localeCompare(b.name,"pt-BR"))}
function elapsedText(ts){if(!ts)return"";let sec=Math.max(0,Math.floor((Date.now()-ts)/1000));if(sec<60)return sec+" s";let min=Math.floor(sec/60);if(min<60)return min+" min";let h=Math.floor(min/60),m=min%60;return h+" h"+(m?" "+m+" min":"")}
async function refreshLibrasLab(){applyEditionUI();let warn=$("#ll-not-native"),statusCard=$("#ll-status-card"),sessionCard=$("#ll-session-card"),detCard=$("#ll-detected-card");if(!warn||!statusCard)return;let native=personalEditionAvailable();warn.classList.toggle("hidden",native);statusCard.classList.toggle("hidden",!native);sessionCard.classList.toggle("hidden",!native);if(!native){detCard.classList.add("hidden");return}let st=getNativeState()||{},enabled=!!st.accessibilityEnabled,live=!!st.captureEnabled;$("#ll-accessibility-status").textContent=enabled?"Conectado ao LibrasLab":"Permissão ainda não ativada";$("#ll-accessibility-dot").className="status-dot "+(live?"live":enabled?"ok":"");$("#ll-enable").classList.toggle("hidden",enabled);$("#ll-start").classList.toggle("hidden",live);$("#ll-start").disabled=!enabled;$("#ll-open").classList.toggle("hidden",!live);$("#ll-stop").classList.toggle("hidden",!live);let raw=Array.isArray(st.detections)?st.detections:[];$("#ll-session-info").textContent=live?"🟣 Captura ativa · "+raw.length+" textos únicos lidos · "+elapsedText(st.sessionStartedAt):raw.length?"Aula finalizada. Revise os sinais detectados abaixo.":"Inicie a captura antes de abrir o LibrasLab.";if(!raw.length){detCard.classList.add("hidden");S.librasLabCandidates=[];return}detCard.classList.remove("hidden");$("#ll-detected-list").innerHTML='<div class="ll-progress">🔎 Conferindo '+raw.length+' textos com o catálogo do Studio…</div>';let candidates=await buildLibrasLabCandidates(raw);S.librasLabCandidates=candidates;$("#ll-detected-title").textContent=candidates.length+" "+(candidates.length===1?"sinal":"sinais");$("#ll-detected-meta").textContent=raw.length+" textos lidos do LibrasLab · "+candidates.length+" reconhecidos como sinais no catálogo.";$("#ll-detected-list").innerHTML=candidates.length?candidates.map((c,i)=>'<label class="ll-candidate '+(c.existing?"existing":"")+'"><input type="checkbox" data-ll-index="'+i+'" '+(c.uiLikely?"":"checked")+'><div><b>'+esc(c.name)+'</b><small>'+c.count+' ocorrência(s) · '+(c.existing?"já está na biblioteca":"novo sinal")+(c.uiLikely?" · pode ser botão da interface":"")+'</small></div>'+(c.existing?'<span class="ll-badge">já salvo</span>':"")+'</label>').join(""):'<div class="ll-empty">Ainda não reconheci nomes de sinais nesta sessão. Continue a aula e toque em ↻ Atualizar.</div>'}
function llOpenAccessibility(){if(nativeBridgeAvailable())window.LibrasNative.openAccessibilitySettings()}
function llStart(){if(!nativeBridgeAvailable())return;if(!(getNativeState()?.accessibilityEnabled))return llOpenAccessibility();window.LibrasNative.startLibrasLabCapture();refreshLibrasLab();setTimeout(()=>window.LibrasNative.openLibrasLab(),180)}
function llOpen(){if(nativeBridgeAvailable())window.LibrasNative.openLibrasLab()}
function llStop(){if(!nativeBridgeAvailable())return;window.LibrasNative.stopLibrasLabCapture();setTimeout(refreshLibrasLab,120)}
function llClear(){if(!nativeBridgeAvailable())return;window.LibrasNative.stopLibrasLabCapture();window.LibrasNative.clearLibrasLabDetections();S.librasLabCandidates=[];refreshLibrasLab()}
async function llImport(){if(!S.session)return toast("Entre na sua conta primeiro.");let selected=$$("[data-ll-index]:checked").map(x=>S.librasLabCandidates[+x.dataset.llIndex]).filter(Boolean);if(!selected.length)return toast("Selecione pelo menos um sinal.");$("#ll-import").disabled=true;let added=0,due=0,failed=[];try{for(let c of selected){let existing=S.signs.find(x=>x.norm===c.norm);if(existing){let r=S.reviews.find(x=>x.norm===c.norm);if(r){let now=new Date().toISOString(),patch={due_at:now,updated_at:now};let{error}=await sb.from("review_state").update(patch).eq("user_id",S.session.user.id).eq("norm",c.norm);if(error)throw error;Object.assign(r,patch);due++}continue}let picked=await firstPlayable(c.options,{timeout:3500,max:10});if(!picked){failed.push(c.name);continue}await save(c.name,picked,null,"libraslab_bridge");added++}if(nativeBridgeAvailable()){window.LibrasNative.stopLibrasLabCapture();window.LibrasNative.clearLibrasLabDetections()}cache();render();let msg="✅ "+added+" novo(s) sinal(is) adicionado(s)";if(due)msg+=" · "+due+" revisão(ões) trazidas para agora";if(failed.length)msg+=" · "+failed.length+" sem vídeo disponível";toast(msg);S.librasLabCandidates=[];refreshLibrasLab()}catch(e){console.error(e);toast("Não consegui concluir toda a importação.")}finally{$("#ll-import").disabled=false}}
window.addEventListener("librasstudio-native-resume",()=>refreshLibrasLab());
window.addEventListener("focus",()=>{if($("#libraslab")?.classList.contains("active"))refreshLibrasLab()});
document.addEventListener("visibilitychange",()=>{if(!document.hidden&&$("#libraslab")?.classList.contains("active"))refreshLibrasLab()});
function installNativeTouchNavigation(){
  if(!IS_NATIVE_ANDROID||window.__lsNativeTouchNav)return;
  window.__lsNativeTouchNav=true;
  document.addEventListener("pointerup",e=>{
    if(e.pointerType&&e.pointerType!=="touch")return;
    const nav=e.target.closest("nav [data-view]");
    if(nav){
      e.preventDefault();
      const v=nav.dataset.view;
      nav.dataset.nativeTapAt=String(Date.now());
      if(v==="more"){
        const sheet=$("#more");
        if(sheet)sheet.classList.remove("hidden");
      }else go(v);
      return;
    }
    const quick=e.target.closest("[data-go]");
    if(quick){
      e.preventDefault();
      go(quick.dataset.go);
    }
  },{passive:false});
}
function installDelegatedNavigation(){
  if(window.__lsDelegatedNav)return;window.__lsDelegatedNav=true;
  document.addEventListener("click",e=>{
    const cat=e.target.closest("[data-home-cat],[data-cat]");
    if(cat){e.preventDefault();let name=cat.dataset.homeCat||cat.dataset.cat;if(cat.dataset.homeCat){go("explore");setTimeout(()=>openCat(name),0)}else openCat(name);return}
    const nav=e.target.closest("[data-go]");
    if(nav){e.preventDefault();go(nav.dataset.go)}
  });
}
function wire(){$("#auth-form").onsubmit=async e=>{e.preventDefault();let{error}=await sb.auth.signInWithPassword({email:$("#email").value,password:$("#password").value});$("#auth-status").textContent=error?error.message:""};$("#signup").onclick=async()=>{let{error}=await sb.auth.signUp({email:$("#email").value,password:$("#password").value});$("#auth-status").textContent=error?error.message:"Conta criada. Confira seu e-mail."};$("#logout").onclick=async()=>{try{await sb.auth.signOut({scope:"local"})}finally{forgetRememberedUser();S.session=null;S.signs=[];S.cats=[];S.reviews=[];S.study=[];authUI()}};$("#sync").onclick=$("#sync-now").onclick=sync;$("#app-update").onclick=$("#update-now").onclick=forceAppUpdate;let mu=$("#mobile-update-now");if(mu)mu.onclick=forceAppUpdate;$("#ll-enable").onclick=llOpenAccessibility;$("#ll-start").onclick=llStart;$("#ll-open").onclick=llOpen;$("#ll-stop").onclick=llStop;$("#ll-refresh").onclick=refreshLibrasLab;$("#ll-import").onclick=llImport;$("#ll-clear").onclick=llClear;$$("nav [data-view]").forEach(b=>b.onclick=()=>{if(IS_NATIVE_ANDROID&&Date.now()-Number(b.dataset.nativeTapAt||0)<700)return;if(b.dataset.view==="more"){let s=$("#more");if(s)s.classList.toggle("hidden")}else go(b.dataset.view)});$$(".side-nav [data-view]").forEach(b=>b.onclick=()=>go(b.dataset.view));$$("[data-go]").forEach(b=>b.onclick=()=>go(b.dataset.go));$$("[data-mode]").forEach(b=>b.onclick=()=>{$$("[data-mode]").forEach(x=>x.classList.toggle("active",x===b));$("#sign-box").classList.toggle("hidden",b.dataset.mode!=="sign");$("#phrase-box").classList.toggle("hidden",b.dataset.mode!=="phrase")});$("#create-search").onclick=createSign;$("#variants").onclick=variants;$("#video-file").onchange=e=>uploadVideo(e.target.files[0]);$("#phrase-search")&&($("#phrase-search").onclick=phrase);$("#explore-search").oninput=exploreCats;$("#global-search").onkeydown=e=>{if(e.key==="Enter"){let q=e.currentTarget.value.trim();go("explore");$("#create-name").value=q;$("#create-name").focus()}};$("#study-search").oninput=study;$("#library-search").oninput=library;$("#library-cat").onchange=library;$("#new-cat").onclick=newCat;$("#move").onclick=move;$("#delete").onclick=del;$("#review-start").onclick=()=>{S.queue=queue();S.i=0;$("#review-setup").classList.add("hidden");card()};$("#reveal").onclick=()=>{$("#review-media").classList.remove("hidden");$("#ratings").classList.remove("hidden");$("#reveal").classList.add("hidden")};$$("[data-rate]").forEach(b=>b.onclick=()=>rate(b.dataset.rate));$("#again-session").onclick=()=>{$("#review-setup").classList.remove("hidden");$("#review-done").classList.add("hidden")};$("#close-modal").onclick=()=>$("#modal").classList.add("hidden");$("#modal").onclick=e=>{if(e.target===$("#modal"))$("#modal").classList.add("hidden")}}
async function revalidateSessionAndSync(){
  if(!navigator.onLine){localStatus("📴 offline · dados locais");return}
  try{
    let{data:{session},error}=await sb.auth.getSession();
    if(error)throw error;
    if(session){S.session=session;rememberSession(session);cached(session.user.id);authUI();await sync({silent:true})}
    else if(S.session?.offline){forgetRememberedUser();S.session=null;authUI()}
  }catch(e){console.warn("revalidar sessão",e);if(S.session)localStatus("📴 dados locais")}
}
async function init(){
  let remembered=rememberedUser();
  if(remembered){
    S.session=offlineSession(remembered);
    cached(remembered.id);
    authUI();render();
    localStatus(navigator.onLine?"☁️ dados locais":"📴 offline · dados locais");
  }
  sb=supabase.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:!IS_NATIVE_ANDROID,storage:window.localStorage}});
  wire();installDelegatedNavigation();if(window.LSHydrateIcons)LSHydrateIcons(document);installNativeTouchNavigation();applyEditionUI();
  sb.auth.onAuthStateChange((event,session)=>{
    if(session){
      S.session=session;rememberSession(session);cached(session.user.id);authUI();
      if(navigator.onLine)setTimeout(()=>sync({silent:true}),0);
    }else if(event==="SIGNED_OUT"){
      forgetRememberedUser();S.session=null;S.signs=[];S.cats=[];S.reviews=[];S.study=[];authUI();
    }
  });
  try{
    let{data:{session},error}=await sb.auth.getSession();
    if(error)throw error;
    if(session){S.session=session;rememberSession(session);cached(session.user.id);authUI();if(navigator.onLine)sync({silent:true});else localStatus("📴 offline · dados locais")}
    else if(!remembered){S.session=null;authUI()}
    else if(navigator.onLine){forgetRememberedUser();S.session=null;authUI()}
  }catch(e){console.warn("sessão inicial",e);if(S.session){cached();render();localStatus("📴 dados locais")}else authUI()}
  window.addEventListener("online",()=>{localStatus("☁️ reconectando…");revalidateSessionAndSync()});
  window.addEventListener("offline",()=>{if(S.session){cached();render();localStatus("📴 offline · dados locais")}});
  setupServiceWorker();
  checkAppUpdate();
}init();